function mapsSearch(place){return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(place+', India')}
function stopMapSearch(place){const flat=document.getElementById('flatAddress')?.value.trim();if(place==='Home')return mapsSearch(flat||'Pune');if(place==='Pune')return mapsSearch('Pune');return mapsSearch(place)}
function routeUrl(day){const flat=document.getElementById('flatAddress')?.value.trim()||'Pune';const departure=document.getElementById('departurePoint')?.value.trim();let locs=day.stops.map(s=>s[4]).filter(x=>x!=='Home'&&x!=='Pune');let origin=flat;let destination=flat;if(day.n===6&&departure){destination=departure;}const originText=origin==='Pune'?'Pune, India':(origin+', Pune, India');const destinationText=destination==='Pune'?'Pune, India':(destination.includes('Pune')?destination:destination+', India');const waypoints=locs.slice(0,8).join('|');let u='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(originText)+'&destination='+encodeURIComponent(destinationText)+'&travelmode=driving';if(waypoints)u+='&waypoints='+encodeURIComponent(waypoints);return u}
const embeddedPuneArt={"wallpaper":"data:image/webp;base64,","shaniwar":"data:image/webp;base64,","lalmahal":"data:image/webp;base64,","dagdusheth":"data:image/webp;base64,","pataleshwar":"data:image/webp;base64,","kelkar":"data:image/webp;base64,","agakhan":"data:image/webp;base64,","sinhagad":"data:image/webp;base64,","khadakwasla":"data:image/webp;base64,","parvati":"data:image/webp;base64,","chaturshringi":"data:image/webp;base64,","market":"data:image/webp;base64,","food":"data:image/webp;base64,"};
function fallbackImage(img,emoji,label){
 const s=String(label||img.alt||'Pune').toLowerCase();
 let key='wallpaper';
 if(/shaniwar/.test(s))key='shaniwar';
 else if(/lal mahal/.test(s))key='lalmahal';
 else if(/dagdusheth|ganpati/.test(s))key='dagdusheth';
 else if(/pataleshwar/.test(s))key='pataleshwar';
 else if(/kelkar|museum/.test(s))key='kelkar';
 else if(/aga khan/.test(s))key='agakhan';
 else if(/sinhagad|fort/.test(s))key='sinhagad';
 else if(/khadakwasla|dam|panshet/.test(s))key='khadakwasla';
 else if(/parvati/.test(s))key='parvati';
 else if(/chaturshringi/.test(s))key='chaturshringi';
 else if(/tulshi|tulsi|market|mandai/.test(s))key='market';
 img.onerror=null;
 img.src=embeddedPuneArt[key]||embeddedPuneArt.wallpaper;
 img.classList.add('illustrated-fallback');
 img.title='Illustrated Pune postcard fallback; the linked map still opens normally.';
}
function renderDays(){const box=document.getElementById('daysContainer');box.innerHTML='';days.forEach(d=>{const el=document.createElement('article');el.className='day';el.id='day'+d.n;const stops=d.stops.map((s,i)=>`<div class="stop"><div class="stop-icon">${s[1]}</div><div class="time">${s[0]}</div><div><h4>${s[2]}</h4><p>${s[3]}</p><div class="duration">${i<d.stops.length-1?(i===0?'Travel between stops · allow buffer':'Next leg · traffic dependent'):''}</div></div><div class="stop-actions"><a class="btn small ghost" href="${stopMapSearch(s[4])}" target="_blank" rel="noopener">Map ↗</a></div></div>${i<d.stops.length-1?'<div class="travel-gap">↳ Transfer / walk · allow for traffic and parking</div>':''}`).join('');el.innerHTML=`<div class="day-top"><div><div class="day-no">Day ${d.n} · ${d.n===4?'Adventure day':d.n===5?'Slow day':'Pune moments'}</div><h3>${d.title}</h3><div class="day-route">${d.route}</div><div class="day-actions" style="margin-top:13px"><a class="btn small" href="${routeUrl(d)}" target="_blank" rel="noopener">Open full Day ${d.n} route in Google Maps ↗</a><button class="btn small ghost" onclick="toggleDay(${d.n})">Show / hide schedule</button></div></div><img class="day-hero-img" src="${embeddedPunePhotos[d.img]||embeddedPuneArt.wallpaper}" alt="${d.alt}" loading="lazy" referrerpolicy="no-referrer" onerror="fallbackImage(this,'','${d.alt.replace(/'/g, '')}')" /></div><div class="day-body" id="daybody${d.n}"><div class="good-to-know"><b>Good to know:</b> ${d.tip}</div><div class="timeline">${stops}</div><div class="day-foot"><label class="checkline"><input type="checkbox" class="day-check" data-day="${d.n}" /> Mark Day ${d.n} complete</label><a class="btn small ghost" href="${mapsSearch(d.stops.filter(s=>s[4]!=='Home'&&s[4]!=='Pune')[0]?.[4]||'Pune')}" target="_blank" rel="noopener">Open first stop ↗</a></div></div>`;box.appendChild(el)});document.querySelectorAll('.day-check').forEach(c=>{c.checked=localStorage.getItem('pune-day-'+c.dataset.day)==='1';c.addEventListener('change',()=>{localStorage.setItem('pune-day-'+c.dataset.day,c.checked?'1':'0');showToast(c.checked?'Day marked complete':'Day reopened')})})}
function toggleDay(n){const body=document.getElementById('daybody'+n);body.style.display=body.style.display==='none'?'block':'none'}
let allOpen=true;function toggleAllDays(){allOpen=!allOpen;days.forEach(d=>document.getElementById('daybody'+d.n).style.display=allOpen?'block':'none');document.getElementById('toggleDays').textContent=allOpen?'Collapse all days':'Expand all days'}
function renderGallery(){document.getElementById('galleryGrid').innerHTML=photos.map(p=>`<figure class="photo"><a href="${mapsSearch(p[3])}" target="_blank" rel="noopener"><img src="${embeddedPunePhotos[p[2]]||embeddedPuneArt.wallpaper}" alt="Photo-style generated visual of ${p[0]} — ${p[1]}" loading="lazy"><figcaption><b>${p[0]}</b><br><span class="muted">${p[1]} · Open Google Maps ↗</span></figcaption></a><div class="photo-source"><a href="${p[5]}" target="_blank" rel="noopener">Documentary photo / reference ↗</a></div></figure>`).join('')}
const tasks=['Comfortable walking shoes with grip','Light, breathable clothes and one modest temple outfit','Reusable water bottle and small day bag','Sun protection: cap, sunglasses and sunscreen','Power bank, charging cable and ID','Light rain layer in monsoon season'];
function renderPacking(){const list=document.getElementById('packingList');list.innerHTML=tasks.map((t,i)=>`<label class="task" id="task${i}"><input type="checkbox" data-task="${i}">${t}</label>`).join('');list.querySelectorAll('input').forEach(c=>{c.checked=localStorage.getItem('pune-pack-'+c.dataset.task)==='1';c.closest('.task').classList.toggle('done',c.checked);c.addEventListener('change',()=>{localStorage.setItem('pune-pack-'+c.dataset.task,c.checked?'1':'0');c.closest('.task').classList.toggle('done',c.checked);updatePacking()})});updatePacking()}
function updatePacking(){const inputs=[...document.querySelectorAll('#packingList input')];const n=inputs.filter(x=>x.checked).length;document.getElementById('packingProgress').style.width=(n/inputs.length*100)+'%';document.getElementById('packingCount').textContent=`${n} / ${inputs.length} ready`}
function updateBudget(){const vals=['foodBudget','transportBudget','entryBudget'].map(id=>Math.max(0,Number(document.getElementById(id).value)||0));const total=vals.reduce((a,b)=>a+b,0);document.getElementById('budgetTotal').textContent='₹'+total.toLocaleString('en-IN');document.getElementById('budgetFill').style.width=Math.min(100,total/14000*100)+'%';['foodBudget','transportBudget','entryBudget'].forEach(id=>localStorage.setItem('pune-'+id,document.getElementById(id).value))}
function saveSettings(){['flatAddress','arrivalPoint','departurePoint'].forEach(id=>localStorage.setItem('pune-'+id,document.getElementById(id).value));showToast('Route details saved in this browser')}
function loadSettings(){['flatAddress','arrivalPoint','departurePoint'].forEach(id=>{const v=localStorage.getItem('pune-'+id);if(v!==null)document.getElementById(id).value=v});['foodBudget','transportBudget','entryBudget'].forEach(id=>{const v=localStorage.getItem('pune-'+id);if(v!==null)document.getElementById(id).value=v})}
function showToast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),2200)}
function mascotTip(){const t=tips[Math.floor(Math.random()*tips.length)];document.getElementById('tipText').textContent=t;showToast('Pune Mitra has a tip for you')}
function downloadBackup(){const data={flatAddress:document.getElementById('flatAddress').value,arrivalPoint:document.getElementById('arrivalPoint').value,departurePoint:document.getElementById('departurePoint').value,packing:tasks.map((t,i)=>({item:t,packed:localStorage.getItem('pune-pack-'+i)==='1'})),days:days.map(d=>({day:d.n,complete:localStorage.getItem('pune-day-'+d.n)==='1'})),budget:{food:document.getElementById('foodBudget').value,transport:document.getElementById('transportBudget').value,entry:document.getElementById('entryBudget').value}};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pune-for-two-trip-checklist.json';a.click();URL.revokeObjectURL(a.href)}
function refreshRouteButtons(){/* Route buttons are generated on render; refresh the days to apply newly entered flat and terminal fields. */const y=window.scrollY;renderDays();window.scrollTo(0,y)}
document.documentElement.style.setProperty('--pune-wallpaper','url(\"'+embeddedPuneArt.wallpaper+'\")');
document.querySelectorAll('img[data-photo]').forEach(img=>{img.src=embeddedPunePhotos[img.dataset.photo]||embeddedPuneArt.wallpaper;});
loadSettings();renderDays();renderGallery();renderPacking();updateBudget();['foodBudget','transportBudget','entryBudget'].forEach(id=>document.getElementById(id).addEventListener('input',updateBudget));['flatAddress','arrivalPoint','departurePoint'].forEach(id=>document.getElementById(id).addEventListener('change',saveSettings));document.getElementById('flatAddress').addEventListener('change',refreshRouteButtons);document.getElementById('departurePoint').addEventListener('change',refreshRouteButtons);
